CREATE TABLE "babies" ("id" TEXT NOT NULL, "nickname" TEXT NOT NULL, "birth_date" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NULL, "dirty" INTEGER NOT NULL DEFAULT 0 CHECK ("dirty" IN (0, 1)), "gender" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "care_logs" ("id" TEXT NOT NULL, "baby_id" TEXT NOT NULL REFERENCES babies (id), "type" TEXT NOT NULL, "started_at" INTEGER NOT NULL, "ended_at" INTEGER NULL, "detail" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_by" TEXT NULL, "updated_at" INTEGER NULL, "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), "dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("dirty" IN (0, 1)), "source" TEXT NOT NULL DEFAULT 'quick', "diary_card_id" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "cry_events" ("id" TEXT NOT NULL, "baby_id" TEXT NOT NULL REFERENCES babies (id), "started_at" INTEGER NOT NULL, "duration_ms" INTEGER NOT NULL, "audio_path" TEXT NULL, "cry_confidence" REAL NOT NULL DEFAULT 0.0, "context_json" TEXT NOT NULL, "prediction_json" TEXT NOT NULL, "predictor_version" TEXT NOT NULL, "auto_triggered" INTEGER NOT NULL DEFAULT 0 CHECK ("auto_triggered" IN (0, 1)), "sync_state" TEXT NOT NULL DEFAULT 'local', "updated_at" INTEGER NULL, "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), "dirty" INTEGER NOT NULL DEFAULT 1 CHECK ("dirty" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "feedbacks" ("id" TEXT NOT NULL, "cry_event_id" TEXT NOT NULL REFERENCES cry_events (id), "resolved_cause" TEXT NOT NULL, "minutes_to_soothe" INTEGER NULL, "note" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("id"));
CREATE TABLE "model_versions" ("version" TEXT NOT NULL, "kind" TEXT NOT NULL, "local_path" TEXT NOT NULL, "sha256" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 0 CHECK ("active" IN (0, 1)), "installed_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), PRIMARY KEY ("version"));
CREATE TABLE "diary_inputs" ("id" TEXT NOT NULL, "baby_id" TEXT NOT NULL REFERENCES babies (id), "input_type" TEXT NOT NULL, "raw_text" TEXT NOT NULL, "age_in_days" INTEGER NOT NULL, "parse_status" TEXT NOT NULL, "prompt_version" TEXT NOT NULL, "model_version" TEXT NULL, "latency_ms" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "diary_cards" ("id" TEXT NOT NULL, "input_id" TEXT NULL REFERENCES diary_inputs (id), "baby_id" TEXT NOT NULL REFERENCES babies (id), "category" TEXT NOT NULL, "kind" TEXT NOT NULL, "care_log_id" TEXT NULL, "event_time" INTEGER NULL, "time_period" TEXT NULL, "sort_time" INTEGER NOT NULL, "diary_date" INTEGER NOT NULL, "attributes" TEXT NOT NULL, "intensity" TEXT NULL, "note" TEXT NULL, "confidence" REAL NULL, "edited_by_user" INTEGER NOT NULL DEFAULT 0 CHECK ("edited_by_user" IN (0, 1)), "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), "updated_at" INTEGER NULL, "deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("deleted" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "daily_summaries" ("id" TEXT NOT NULL, "baby_id" TEXT NOT NULL REFERENCES babies (id), "date" INTEGER NOT NULL, "status" TEXT NOT NULL, "content" TEXT NULL, "source_ids" TEXT NOT NULL, "stats_json" TEXT NOT NULL, "prompt_version" TEXT NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "generated_at" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("baby_id", "date"));
CREATE UNIQUE INDEX care_logs_one_active ON care_logs (baby_id, type) WHERE ended_at IS NULL AND deleted = 0;
CREATE INDEX diary_cards_baby_date ON diary_cards (baby_id, diary_date);
